"""Lease census, causal application census and request activity."""
from common import addresses
from ledger import (Reconciler, T_EVENT, T_LEASE, T_PAYLOAD, T_PROBE, T_RESULT,
                    T_SERVICE, T_TARGET, T_TYPE)
from protocols import signature

_CACHE = {}


def _signature(kind, payload):
    key = (kind, payload)
    try:
        return _CACHE[key]
    except KeyError:
        pass
    value = signature(kind, payload)
    if len(_CACHE) > 300000:
        _CACHE.clear()
    _CACHE[key] = value
    return value


def build(context, records, low, probes):
    """Return (snapshots, request activity) over the query times."""
    leases = context['leases']
    services = context['services']
    requests = context['requests']
    reconciler = Reconciler(records)
    lease_ids = sorted(leases)
    service_ids = sorted(services)
    by_query = {}
    for rid, request in requests.items():
        bucket = by_query.get(request['at'])
        if bucket is None:
            by_query[request['at']] = [rid]
        else:
            bucket.append(rid)
    snapshots = []
    active = {}
    empty = {}
    for at in context['queries']:
        ledger, live = reconciler.advance(at)
        info = {}
        for lease_id in lease_ids:
            lease = leases[lease_id]
            info[lease_id] = [lease['start'] <= at < lease['end'], {}, {}, False]
        for content in live:
            if content[T_TYPE] != 'icmp':
                continue
            lease_id = content[T_LEASE]
            state = info[lease_id]
            if not state[0]:
                continue
            result = content[T_RESULT]
            if result == 'timeout':
                continue
            responder = content[T_TARGET + 1]
            if responder is None:
                continue
            target = content[T_TARGET]
            canary = probes[lease_id][content[T_PROBE]][1]
            if responder == target:
                if result != 'echo':
                    continue
                if canary:
                    state[3] = True
                    continue
                bucket = state[1]
            else:
                if canary:
                    continue
                bucket = state[2]
            event = content[T_EVENT]
            witness = bucket.get(responder)
            if witness is None or event < witness:
                bucket[responder] = event
        clean = {}
        entries = []
        for lease_id in lease_ids:
            state = info[lease_id]
            if not state[0]:
                clean[lease_id] = ('inactive', empty, empty)
                entries.append((lease_id, 'inactive', [], empty, empty, low[lease_id]))
                continue
            conflicts = state[1].keys() & state[2].keys()
            if state[3]:
                label = 'alias'
            elif conflicts:
                label = 'conflict'
            else:
                label = 'usable'
            if label == 'usable':
                internal, external = state[1], state[2]
            else:
                internal, external = empty, empty
            clean[lease_id] = (label, internal, external)
            unresolved = low[lease_id] - internal.keys() - external.keys()
            entries.append((lease_id, label, sorted(conflicts), internal, external, unresolved))
        unbound = 0
        groups = {}
        for content in live:
            if content[T_TYPE] != 'app':
                continue
            lease_id = content[T_LEASE]
            label, internal, external = clean[lease_id]
            if label != 'usable':
                unbound += 1
                continue
            target = content[T_TARGET]
            witness = internal.get(target)
            if witness is None:
                witness = external.get(target)
                if witness is None:
                    unbound += 1
                    continue
            if witness > content[T_EVENT]:
                unbound += 1
                continue
            key = (lease_id, target, content[T_SERVICE])
            bucket = groups.get(key)
            if bucket is None:
                groups[key] = [(content[T_EVENT - 8], content[T_RESULT], content[T_PAYLOAD])]
            else:
                bucket.append((content[T_EVENT - 8], content[T_RESULT], content[T_PAYLOAD]))
        status = {}
        errors = {}
        for key, rows in groups.items():
            kind = services[key[2]]
            top = 0
            for row in rows:
                if row[0] > top:
                    top = row[0]
            latest = [row for row in rows if row[0] == top]
            opened = 0
            closed = 0
            token = None
            agree = True
            failed = 0
            for row in latest:
                if row[1] == 'open':
                    opened += 1
                    value = _signature(kind, row[2])
                    if value is None:
                        failed += 1
                        agree = False
                    elif token is None:
                        token = value
                    elif value != token:
                        agree = False
                elif row[1] == 'closed':
                    closed += 1
            if opened == len(latest) and agree and token is not None:
                label = 'open'
            elif closed == len(latest):
                label = 'closed'
            else:
                label = 'unknown'
            status[key] = label
            if failed:
                errors[key] = failed
        reports = {}
        for key, label in status.items():
            lease_id, target, service_id = key
            bucket = reports.get(lease_id)
            if bucket is None:
                bucket = reports[lease_id] = {}
            service = bucket.get(service_id)
            if service is None:
                service = bucket[service_id] = [set(), set(), 0]
            if label == 'open':
                service[0].add(target)
            elif label == 'closed':
                service[1].add(target)
        for key, failed in errors.items():
            lease_id, target, service_id = key
            bucket = reports.get(lease_id)
            if bucket is None:
                bucket = reports[lease_id] = {}
            service = bucket.get(service_id)
            if service is None:
                service = bucket[service_id] = [set(), set(), 0]
            service[2] += failed
        lease_reports = []
        for lease_id, label, conflicts, internal, external, unresolved in entries:
            report = reports.get(lease_id) or {}
            keys = sorted(external)
            closed_all = bool(keys) and all((lid_key := True) for _ in ())
            services_out = []
            for service_id in service_ids:
                bucket = report.get(service_id)
                if bucket is None:
                    iopen = []
                    iclosed = []
                    eopen = []
                    eclosed = []
                    failed = 0
                else:
                    iopen = addresses(internal.keys() & bucket[0])
                    iclosed = addresses(internal.keys() & bucket[1])
                    eopen = addresses(external.keys() & bucket[0])
                    eclosed = addresses(external.keys() & bucket[1])
                    failed = bucket[2]
                if keys and len(eclosed) == len(keys):
                    ionly = iopen
                else:
                    ionly = []
                services_out.append({'id': service_id,
                                     'internal_open': iopen,
                                     'internal_closed': iclosed,
                                     'external_open': eopen,
                                     'external_closed': eclosed,
                                     'internal_only': ionly,
                                     'protocol_errors': failed})
            lease_reports.append({'lease': lease_id,
                                  'state': label,
                                  'conflicts': addresses(conflicts),
                                  'internal': addresses(internal),
                                  'external': addresses(external),
                                  'unresolved': addresses(unresolved),
                                  'services': services_out})
        for rid in by_query.get(at, ()):
            request = requests[rid]
            label, internal, external = clean[request['lease']]
            target = request['address']
            if target not in internal:
                active[rid] = False
            else:
                state = status.get((request['lease'], target, request['service']))
                active[rid] = state is None or state == 'unknown'
        snapshots.append({'at': at, 'ledger': ledger,
                          'unbound_applications': unbound,
                          'leases': lease_reports})
    return snapshots, active
PYEOF
